head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.contnId;
scwin.gRegEmpNo;
scwin.bbsTypeCd = "7";
scwin.vScrenID = "ULDSTF06008.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    trs_Read.Action = "/lstinvstg/ListCommBoard.do?method=getContentInfo" + "&BBS_TP_CD=" + scwin.bbsTypeCd + "&CONTN_ID=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_ContentsInfo,O:pOutput2=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_save = function() {
    if (dts_fileList.getCellData(1, "fileInfo") == "") {
        dts_fileList.Reset();
    }
    if (tbox_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_title, 100, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return;
    }
    if (!scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.text = "";
        tarea_contn_contn.focus();
        return false;
    }
    var rtn = confirm('내용을 등록 하시겠습니까?');
    if (rtn == 1) {
        dts_ContentsInfo.setCellData(1, "ANS_OBJ_CONTN_ID", "0");
        dts_ContentsInfo.setCellData(1, "LIST_INVSTG_BBS_TP_CD", scwin.bbsTypeCd); // 게시판구분
        dts_ContentsInfo.setCellData(1, "QUES_BZ_TP_CD", "");
        dts_ContentsInfo.setCellData(1, "WRTR_ID", js_emp_no);
        dts_ContentsInfo.setCellData(1, "ISUR_CD", js_dep_cd);
        dts_ContentsInfo.setCellData(1, "REG_TEL_NO", "");
        dts_ContentsInfo.setCellData(1, "WRTR_EMAIL", js_email);
        dts_ContentsInfo.setCellData(1, "QUES_ANS_TP_CD", ""); // 질문1답변2  구분코드 : 1상장
        dts_ContentsInfo.setCellData(1, "LD_MKT_TP_CD", js_market); // 시장구분 : 1유가, 2코스닥
        dts_ContentsInfo.setCellData(1, "LIST_TP_CLSS_CD", "");
        trs_Save.Action = "/lstinvstg/ListCommBoard.do?method=registerContents" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_ContentsInfo,I:pFile=dts_fileList)";
        trs_Save.Post();
    }
};
scwin.fn_update = function() {
    if (tbox_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_title, 100, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return;
    }
    if (!scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.text = "";
        tarea_contn_contn.focus();
        return false;
    }
    var rtn = confirm('수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_ContentsInfo.setCellData(1, "ANS_OBJ_CONTN_ID", "0");
        dts_ContentsInfo.setCellData(1, "LIST_INVSTG_BBS_TP_CD", scwin.bbsTypeCd);
        dts_ContentsInfo.setCellData(1, "QUES_BZ_TP_CD", "");
        dts_ContentsInfo.setCellData(1, "WRTR_ID", js_emp_no);
        dts_ContentsInfo.setCellData(1, "ISUR_CD", js_dep_cd);
        dts_ContentsInfo.setCellData(1, "REG_TEL_NO", "");
        dts_ContentsInfo.setCellData(1, "WRTR_EMAIL", js_email);
        dts_ContentsInfo.setCellData(1, "QUES_ANS_TP_CD", "");
        dts_ContentsInfo.setCellData(1, "LD_MKT_TP_CD", js_market);
        dts_ContentsInfo.setCellData(1, "LIST_TP_CLSS_CD", "");
        trs_Update.Action = "/lstinvstg/ListCommBoard.do?method=modifyContents&CONTN_ID=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Update.KeyValue = "JSP(I:pInput=dts_ContentsInfo,I:pFile=dts_fileList)";
        trs_Update.Post();
    }
};
scwin.fn_delete = function() {
    var rtn = confirm('삭제 하시겠습니까?');
    if (rtn == 1) {

        //dts_ContentsDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ContentsDel.insertRow();
        dts_ContentsDel.setCellData(1, "CONTN_ID", scwin.contnId);
        trs_Delete.Action = "/lstinvstg/ListCommBoard.do?method=removeContents" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput=dts_ContentsDel)";
        trs_Delete.Parameters = "CONTN_ID=" + scwin.contnId;
        trs_Delete.Post();
    }
};
scwin.fn_setFileDataHeader = function() {

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.fn_SetSaveHeader = function() {
    dts_ContentsInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LIST_INVSTG_BBS_INFO_INOUT";
    dts_ContentsInfo.Reset();
    dts_ContentsInfo.insertRow();
};


//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?CONTN_ID=" + scwin.contnId + "&CONTN_SEQ=" + attach_seq + "&gubun=26";
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.fn_searchCode = function(grpCd) {
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='" + grpCd + "'";
    dts_listClassCd.DataID = encodeURI(url);
    dts_listClassCd.reset();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Save_OnSuccess = function() {
    scwin.fn_parentRefresh();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "등록"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.trs_Update_OnSuccess = function() {
    scwin.fn_parentRefresh();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    $c.win.alert(trs_Update.ErrorMsg);
};
scwin.trs_Delete_OnSuccess = async function() {
    scwin.fn_parentRefresh();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.trs_count_OnSuccess = function() {
    $c.win.alert('trs_count.OnSuccess()');
};
scwin.trs_count_OnFail = function() {
    $c.win.alert(trs_count.ErrorMsg);
};
scwin.inf_find_OnClick = function() {
    var filenm = dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename");
    if (scwin.contnId == "input") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
        file_name.setValue(inf_find.getValue());
    }
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        if (scwin.contnId == "input") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            var seq = dts_fileList.getRowPosition();
            for (i = 0; i < dts_fileList.getTotalRow(); i++) {
                if (dts_fileList.getCellData(i, "ATTACH_SEQ") == seq) {
                    seq++;
                    i = 0;
                }
            }
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", seq);
            file_name.setValue(inf_find.getValue());
        }
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
};
scwin.dts_ContentsInfo_OnLoadError = function() {
    $c.win.alert('dts_ContentsInfo.OnLoadError()');
};
scwin.dts_ContentsInfo_OnLoadCompleted = function(rowcount) {
    scwin.gRegEmpNo = dts_ContentsInfo.getCellData(0, "WRTR_ID");
};
scwin.grd_fileList_OnDblClick = function(row, colid) {
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0 && dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename") != "" && dts_fileList.getCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ") != "") {
        $c.elw.fn_filedown(dts_fileList.getCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ"));
    }
};
scwin.btn_save_onclick = function() {
    if (scwin.contnId == "input") {
        scwin.fn_save();
    } else {
        scwin.fn_update();
    }
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.stf.showObj(tbox_mkt_tp, false);
    $c.elw.fn_searchCode("LIST_INVSTG_FAQ_CLSS_CD");
    var parentYn = $c.frame.path("../").scwin.contnId;
    if (parentYn == null || parentYn == "undefined" || parentYn.length == 0) {
        scwin.contnId = "input";
    } else {
        getContnId = $c.frame.path("../").fn_getContnId;
        scwin.contnId = getContnId();
    }
    if (scwin.contnId != "input") {
        scwin.fn_read();
    } else {
        scwin.fn_setFileDataHeader();
        scwin.fn_SetSaveHeader();
    }
};
